import { createContext, useContext, useReducer } from "react";

const NotificationContext = createContext();

const initialState = {
  notifications: [],
};

const notificationReducer = (state, action) => {
  switch (action.type) {
    case "SET_NOTIFICATIONS":
      return { ...state, notifications: action.payload };
    case "UPDATE_NOTIFICATION":
      return {
        ...state,
        notifications: state.notifications.map((n) =>
          n.id === action.payload.id ? { ...n, ...action.payload.data } : n,
        ),
      };
    default:
      return state;
  }
};

export const NotificationProvider = ({ children }) => {
  const [state, dispatch] = useReducer(notificationReducer, initialState);

  return (
    <NotificationContext.Provider value={{ state, dispatch }}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error(
      "useNotifications must be used within a NotificationProvider",
    );
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect } from "react";

const UnsavedChangesContext = createContext();

export const UnsavedChangesProvider = ({ children }) => {
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  // Reset unsaved changes state on form reset/submit events
  useEffect(() => {
    const handleGlobalReset = () => {
      setHasUnsavedChanges(false);
    };

    const handleGlobalSubmit = () => {
      setHasUnsavedChanges(false);
    };

    document.addEventListener("profile-form-reset", handleGlobalReset);
    document.addEventListener("profile-form-submit", handleGlobalSubmit);

    return () => {
      document.removeEventListener("profile-form-reset", handleGlobalReset);
      document.removeEventListener("profile-form-submit", handleGlobalSubmit);
    };
  }, []);

  return (
    <UnsavedChangesContext.Provider
      value={{ hasUnsavedChanges, setHasUnsavedChanges }}
    >
      {children}
    </UnsavedChangesContext.Provider>
  );
};

export const useUnsavedChanges = () => useContext(UnsavedChangesContext);

import React, { Suspense } from "react";
import { Outlet } from "react-router-dom";
import Navbar from "#components/Navbar/Navbar";
import MainLoader from "#components/Loader/MainLoader";
import Footer from "#components/Footer/Footer";
import LeftAds from "#components/LeftAds/LeftAds";
import RightAds from "#components/RightAds/RightAds";
import NavigationGuard from "#components/NavigationGuard/NavigationGuard";
import { NotificationProvider } from "../context/NotificationContext";
import ScrollToTop from "../common/components/ScrollToTop/ScrollToTop";

const Layout = () => {
  return (
    <div className="flex flex-col h-screen">
      <NotificationProvider>
        {/* Navigation Guard to check for unsaved changes */}

        <NavigationGuard />

        {/* header includes Navbar which spans full width */}
        <header
          className="sticky z-10"
          id="header"
          google-side-rail-overlap="false"
        >
          <Navbar />
        </header>

        {/* main content */}
        <div className="flex flex-1">
          <aside className="left-ads-panel flex-1 ">
            <LeftAds />
          </aside>
          <main className="flex-[6] overflow-auto">
            <Suspense fallback={<MainLoader />}>
              <Outlet />
            </Suspense>
          </main>
          <aside className="right-ads-panel flex-1 ">
            <RightAds />
          </aside>
        </div>

        {/* footer */}
        <footer className="">
          <Footer />
        </footer>
        <ScrollToTop />
      </NotificationProvider>
    </div>
  );
};

export default Layout;

//Mock IntersectionObserver for Scroll To Top Button
global.IntersectionObserver = class {
  constructor(callback) {
    this.callback = callback;
  }
  observe() {
    this.callback([{ isIntersecting: false }]);
  }
  unobserve() {}
  disconnect() {}
};

import { render } from "@testing-library/react";
import Layout from "./Layout";

jest.mock("react", () => ({
  ...jest.requireActual("react"),
  Suspense: ({ children }) => <mock-suspense>{children}</mock-suspense>,
}));

jest.mock("react-router-dom", () => ({
  ...jest.requireActual("react-router-dom"),
  useMatches: () => [{ pathname: "/", params: {} }],
}));

// Mock all the custom components because they have their own snapshot tests
jest.mock("#components/Loader/MainLoader");
jest.mock("#components/Navbar/Navbar");
jest.mock("#components/Footer/Footer");
jest.mock("#components/LeftAds/LeftAds");
jest.mock("#components/RightAds/RightAds");
jest.mock("#components/NavigationGuard/NavigationGuard");

describe("Layout", () => {
  it("renders correctly", () => {
    const tree = render(<Layout />);
    expect(tree).toMatchSnapshot();
  });
});

export const validateIsDefined = (value) => typeof value !== "undefined";

export const validateString = (stringValue, isEmptyCheck = true) => {
  const result = typeof stringValue === "string";

  if (isEmptyCheck) {
    return result && Boolean(stringValue.length);
  }

  return result;
};

export const validateObject = (objectValue, isEmptyCheck = false) => {
  const result = typeof objectValue === "object" && objectValue !== null;

  if (isEmptyCheck) {
    return result && Boolean(Object.keys(objectValue).length);
  }

  return result;
};

export const validateArray = (arrayValue, isEmptyCheck = true) => {
  const result = validateObject(arrayValue) && Array.isArray(arrayValue);

  if (isEmptyCheck) {
    return result && Boolean(arrayValue.length);
  }

  return result;
};

