                    ${isTextOnRight ? "sm:pr-[1.5rem]" : "sm:pl-[1.5rem]"} p-2`}
      >
        {image && (
          <img
            src={image}
            alt={title}
            className="rounded-xl object-contain h-auto sm:max-h-64 md:max-h-72 lg:max-h-80 w-auto max-w-full"
          />
        )}
