      </div>

      {/* Text Content Container: takes 50% width on sm screens. Inner padding adjusts for step number. */}
      <div
        className={`w-full sm:w-1/2 flex items-stretch order-3 sm:order-none p-2 ${
          isTextOnRight ? "sm:pl-0" : "sm:pr-0"
