import React, { useState, useEffect, useRef } from "react";
import {
  FiPhoneCall,
  FiVideo,
  FiMic,
  FiMicOff,
  FiVideoOff,
} from "react-icons/fi";

const CallModal = ({ isOpen, onClose, callType }) => {
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOn, setIsVideoOn] = useState(true);
  const [stream, setStream] = useState(null);
  const videoRef = useRef(null);

  useEffect(() => {
    if (isOpen) {
      startMedia();
    } else {
      stopMedia();
    }
  }, [isOpen]);

  const startMedia = async () => {
    try {
      const mediaConstraints = {
        audio: true,
        video: callType === "video",
      };

      const mediaStream =
        await navigator.mediaDevices.getUserMedia(mediaConstraints);
      setStream(mediaStream);

      if (videoRef.current && callType === "video") {
        videoRef.current.srcObject = mediaStream;
        try {
          await videoRef.current.play();
        } catch (err) {
          console.error("Error playing initial video:", err);
        }
      }
    } catch (error) {
      console.error("Error accessing media devices:", error);
      alert("Could not access camera/microphone. Please check permissions.");
    }
  };

  const stopMedia = () => {
    if (stream) {
      stream.getTracks().forEach((track) => {
        track.stop();
      });
      setStream(null);
      if (videoRef.current) {
        videoRef.current.srcObject = null;
      }
    }
  };

  // Toggle audio mute state
  const toggleMute = () => {
    if (stream) {
      const audioTracks = stream.getAudioTracks();
      audioTracks.forEach((track) => {
        track.enabled = !track.enabled;
      });
      setIsMuted(!isMuted);
    }
  };

  const toggleVideo = async () => {
    if (stream) {
      const videoTracks = stream.getVideoTracks();
      videoTracks.forEach((track) => {
        track.stop();
        stream.removeTrack(track);
      });

      if (!isVideoOn) {
        // If turning video back on
        try {
          // Get new video stream
          const newVideoStream = await navigator.mediaDevices.getUserMedia({
            video: true,
          });

          // Get the new video track
          const newVideoTrack = newVideoStream.getVideoTracks()[0];

          // Add the new track to the existing stream
          stream.addTrack(newVideoTrack);

          // Update video element
          if (videoRef.current) {
            videoRef.current.srcObject = null;
            videoRef.current.srcObject = stream;
            try {
              await videoRef.current.play();
            } catch (err) {
              console.error("Error playing video after toggle:", err);
            }
          }
        } catch (error) {
          console.error("Error restarting video:", error);
          return;
        }
      }

      setIsVideoOn(!isVideoOn);
    }
  };

  // Don't render if modal is not open
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center">
      <div className="bg-white p-6 rounded-lg shadow-lg w-96">
        {/* Modal Header */}
        <h2 className="text-xl font-bold mb-4">
          {callType === "audio" ? (
            <div className="flex items-center space-x-2">
              <FiPhoneCall className="text-blue-500" />
              <span>Audio Call</span>
            </div>
          ) : (
            <div className="flex items-center space-x-2">
              <FiVideo className="text-blue-500" />
              <span>Video Call</span>
            </div>
          )}
        </h2>

        {/* Video Preview */}
        {callType === "video" && (
          <div className="mb-4 bg-gray-100 rounded-lg overflow-hidden">
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              className="w-full h-48 object-cover"
            />
          </div>
        )}

        {/* Media Controls */}
        <div className="flex justify-around mb-6">
          {/* Mute Button */}
          <button
            onClick={toggleMute}
            className={`flex flex-col items-center p-3 rounded-lg ${
              isMuted ? "bg-red-100" : "bg-gray-100"
            } hover:bg-gray-200 transition-colors`}
          >
            {isMuted ? (
              <FiMicOff className="text-red-500 text-2xl" />
            ) : (
              <FiMic className="text-green-500 text-2xl" />
            )}
            <span className="text-sm mt-1">{isMuted ? "Unmute" : "Mute"}</span>
          </button>

          {/* Video Toggle Button */}
          {callType === "video" && (
            <button
              onClick={toggleVideo}
              className={`flex flex-col items-center p-3 rounded-lg ${
                !isVideoOn ? "bg-red-100" : "bg-gray-100"
              } hover:bg-gray-200 transition-colors`}
            >
              {isVideoOn ? (
                <FiVideo className="text-green-500 text-2xl" />
              ) : (
                <FiVideoOff className="text-red-500 text-2xl" />
              )}
              <span className="text-sm mt-1">
                {isVideoOn ? "Turn Off Video" : "Turn On Video"}
              </span>
            </button>
          )}
        </div>

        {/* Action Buttons */}
        <button
          className="w-full bg-blue-500 text-white py-2 rounded-md hover:bg-blue-600 transition-colors"
          onClick={() => {
            console.log("Call started with settings:", {
              isMuted,
              isVideoOn,
              stream,
            });
            onClose();
          }}
        >
          Start Call
        </button>

        <button
          className="w-full mt-3 bg-gray-500 text-white py-2 rounded-md hover:bg-gray-600 transition-colors"
          onClick={() => {
            stopMedia(); // Clean up media before closing
            onClose();
          }}
        >
          Close
        </button>
      </div>
    </div>
  );
};

export default CallModal;

import React, { useState, useEffect, useRef } from "react";
import Select from "react-select";
import { useTranslation } from "react-i18next";
import PHONECODESEN from "../../utils/phone-codes-en";
import { getPhoneCodeslist } from "../../utils/utils";

const COUNTRY_CODE_API =
  "https://raw.githubusercontent.com/dr5hn/countries-states-cities-database/master/countries.json";

function OrganizationDetails({ setHasUnsavedChanges }) {
  const { t } = useTranslation();
  const [isEditing, setIsEditing] = useState(false);
  const organizationNameRef = useRef(null);

  const [errors, setErrors] = useState({});

  const [organizationInfo, setOrganizationInfo] = useState({
    organizationName: "",
    phoneNumber: "",
    phoneCountryCode: "",
    email: "",
    url: "",
    streetAddress: "",
    streetAddress2: "",
    city: "",
    state: "",
    zipCode: "",
    organizationType: t("NON_PROFIT"),
  });
  const phoneCodeOptions = getPhoneCodeslist(PHONECODESEN);

  useEffect(() => {
    fetch(COUNTRY_CODE_API)
      .then((response) => response.json())
      .then((data) => {
        const countries = data.map((country) => ({
          value: country.phone_code,
          label: `${country.name} (+${country.phone_code})`,
        }));

        const sortedCountries = countries.sort((a, b) => {
          if (a.label.includes("United States")) return -1;
          if (a.label.includes("Canada")) return -1;
          return 0;
        });

        setCountryOptions(sortedCountries);
      })
      .catch((error) => console.error("Error fetching country codes:", error));

    const savedOrganizationInfo = JSON.parse(
      localStorage.getItem("organizationInfo"),
    );
    if (savedOrganizationInfo) {
      setOrganizationInfo(savedOrganizationInfo);
    }
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;

    let errorMsg = "";
    if (name == "email") {
      if (!/^[a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z]{2,}$/.test(value)) {
        errorMsg = "Please enter a valid Email Address.";
      }
    }
    if (name == "phoneNumber") {
      if (!/^\d{10}$/.test(value)) {
        errorMsg = "Please enter a valid Phone Number.";
      }
    }
    if (name == "url") {
      if (!/^https?:\/\/.+\.[a-zA-Z]{2,}$/.test(value)) {
        errorMsg = "Please enter a valid URL.";
      }
    }

    setErrors((prevErrors) => ({ ...prevErrors, [name]: errorMsg }));

    setOrganizationInfo((prevInfo) => ({
      ...prevInfo,
      [name]: value,
    }));
    setHasUnsavedChanges(true);
  };

  const handleEditClick = () => {
    setIsEditing(true);
    setTimeout(() => {
      if (organizationNameRef.current) {
        organizationNameRef.current.focus();
      }
    }, 0);
  };

  const handleSaveClick = () => {
    let hasError = false;
    Object.values(errors).forEach((error) => {
      if (error !== "") {
        hasError = true;
      }
    });
    if (hasError) {
      alert("Please fix the Errors before saving.");
      return;
    }

    setIsEditing(false);
    localStorage.setItem("organizationInfo", JSON.stringify(organizationInfo));
    setHasUnsavedChanges(false);
  };

  const handleCancelClick = () => {
    setIsEditing(false);
    setHasUnsavedChanges(false);
  };

  return (
    <div className="flex flex-col p-8 rounded-lg w-full max-w-4xl mb-8 bg-white shadow-md">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("ORGANIZATION_NAME")}
          </label>
          {isEditing ? (
            <input
              ref={organizationNameRef}
              type="text"
              name="organizationName"
              value={organizationInfo.organizationName}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.organizationName || ""}
            </p>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-8 mb-6">
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("ORGANIZATION_TYPE")}
          </label>
          {isEditing ? (
            <div>
              <label className="inline-flex items-center">
                <input
                  type="radio"
                  name="organizationType"
                  value={t("NON_PROFIT")}
                  checked={
                    organizationInfo.organizationType === t("NON_PROFIT")
                  }
                  onChange={handleInputChange}
                  className="form-radio h-4 w-4 text-blue-500"
                />
                <span className="ml-2">{t("NON_PROFIT")}</span>
              </label>
              <label className="inline-flex items-center ml-6">
                <input
                  type="radio"
                  name="organizationType"
                  value={t("FOR_PROFIT")}
                  checked={
                    organizationInfo.organizationType === t("FOR_PROFIT")
                  }
                  onChange={handleInputChange}
                  className="form-radio h-4 w-4 text-blue-500"
                />
                <span className="ml-2">{t("FOR_PROFIT")}</span>
              </label>
            </div>
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.organizationType}
            </p>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("PHONE_NUMBER")}
          </label>
          {isEditing ? (
            <div className="flex">
              <Select
                name="phoneCountryCode"
                value={phoneCodeOptions.find(
                  (option) => option.code === organizationInfo.phoneCountryCode,
                )}
                getOptionLabel={(option) =>
                  `${option.country} (${option.dialCode})`
                }
                getOptionValue={(option) => option.code}
                options={phoneCodeOptions}
                onChange={(selectedOption) =>
                  handleInputChange({
                    target: {
                      name: "phoneCountryCode",
                      value: selectedOption.code,
                    },
                  })
                }
                className="w-1/3 mr-2"
              />
              <input
                type="text"
                name="phoneNumber"
                value={organizationInfo.phoneNumber}
                onChange={handleInputChange}
                className="appearance-none block w-2/3 bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
              />
            </div>
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.phoneCountryCode}{" "}
              {organizationInfo.phoneNumber || ""}
            </p>
          )}
          {errors.phoneNumber && (
            <p className="text-red-500 text-xs">{errors.phoneNumber}</p>
          )}
        </div>
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            Email
          </label>
          {isEditing ? (
            <input
              type="email"
              name="email"
              value={organizationInfo.email}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.email || ""}
            </p>
          )}
          {errors.email && (
            <p className="text-red-500 text-xs">{errors.email}</p>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-8 mb-6">
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            URL
          </label>
          {isEditing ? (
            <input
              type="text"
              name="url"
              value={organizationInfo.url}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.url || ""}
            </p>
          )}
          {errors.url && <p className="text-red-500 text-xs">{errors.url}</p>}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("ADDRESS", { optional: "" })}
          </label>
          {isEditing ? (
            <input
              type="text"
              name="streetAddress"
              value={organizationInfo.streetAddress}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.streetAddress || ""}
            </p>
          )}
        </div>
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("ADDRESS", { optional: " 2" })}
          </label>
          {isEditing ? (
            <input
              type="text"
              name="streetAddress2"
              value={organizationInfo.streetAddress2}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.streetAddress2 || ""}
            </p>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-6">
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("CITY")}
          </label>
          {isEditing ? (
            <input
              type="text"
              name="city"
              value={organizationInfo.city}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.city || ""}
            </p>
          )}
        </div>
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("STATE")}
          </label>
          {isEditing ? (
            <input
              type="text"
              name="state"
              value={organizationInfo.state}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.state || ""}
            </p>
          )}
        </div>
        <div>
          <label className="block tracking-wide text-gray-700 text-xs font-bold mb-2">
            {t("ZIP_CODE")}
          </label>
          {isEditing ? (
            <input
              type="text"
              name="zipCode"
              value={organizationInfo.zipCode}
              onChange={handleInputChange}
              className="appearance-none block w-full bg-white-200 text-gray-700 border border-gray-300 rounded py-2 px-4 leading-tight focus:outline-none focus:bg-white focus:border-gray-500"
            />
          ) : (
            <p className="text-lg text-gray-900">
              {organizationInfo.zipCode || ""}
            </p>
          )}
        </div>
      </div>

      <div className="flex justify-center mt-6">
        {!isEditing ? (
          <button
            className="py-2 px-4 bg-blue-500 text-white rounded-md hover:bg-blue-600"
            onClick={handleEditClick}
          >
            {t("EDIT")}
          </button>
        ) : (
          <>
            <button
              className="py-2 px-4 bg-blue-500 text-white rounded-md mr-2 hover:bg-blue-600"
              onClick={handleSaveClick}
            >
              {t("SAVE")}
            </button>
            <button
              className="py-2 px-4 bg-gray-500 text-white rounded-md hover:bg-gray-600"
              onClick={handleCancelClick}
            >
              {t("CANCEL")}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

export default OrganizationDetails;

